// Utils de dates
// src/utils/DateUtils.js
import { startOfWeek, endOfWeek, format } from "date-fns";
import { fr } from "date-fns/locale";

/**
 * Retourne la semaine actuelle :
 * - date de début (lundi)
 * - date de fin (dimanche)
 * - versions formatées FR
 */
export const getCurrentWeekRange = () => {
  const now = new Date();

  const weekStart = startOfWeek(now, { weekStartsOn: 1 }); // lundi
  const weekEnd = endOfWeek(now, { weekStartsOn: 1 });     // dimanche

  return {
    weekStart,
    weekEnd,
    formattedStart: format(weekStart, "dd MMMM yyyy", { locale: fr }),
    formattedEnd: format(weekEnd, "dd MMMM yyyy", { locale: fr }),
  };
};

/**
 * Formatte une date au format français court.
 * Exemple : "05 janv"
 */
export const formatDateFR = (date) =>
  date.toLocaleDateString("fr-FR", {
    day: "2-digit",
    month: "short",
  });

/**
 * Retourne la semaine (lundi → dimanche) d'une date donnée.
 * Utile si tu veux afficher la semaine d'une session.
 */
export const getWeekRange = (date) => {
  const d = new Date(date);
  const day = d.getDay(); // 0 = dimanche

  const monday = new Date(d);
  monday.setDate(d.getDate() - ((day + 6) % 7));

  const sunday = new Date(monday);
  sunday.setDate(monday.getDate() + 6);

  return { start: monday, end: sunday };
};
